"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["58272"],{24767(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>d,frontMatter:()=>i,contentTitle:()=>o,toc:()=>h,assets:()=>l});var a=JSON.parse('{"id":"qiangguo/briefsummary","title":"","description":"[Girl Who Likes Mathematics] posted on 2003-07-09 1536","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/briefsummary.md","sourceDirName":"qiangguo","slug":"/qiangguo/briefsummary","permalink":"/en/qiangguo/briefsummary","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"briefsummary","title":"","hide_table_of_contents":true,"sidebar_label":"January Summary and Farewell to the Forum, Plus Revealing the Original Aliases and the Truth About the Japanese Couplet"},"sidebar":"qiangguoSidebar","previous":{"title":"The So-Called \\"Second Wu Jinglian\\" Larry Lang Phenomenon Is Nothing But Dogs Fighting Over Bones Between the New Left and Liberals","permalink":"/en/qiangguo/lxpphenomenon"},"next":{"title":"Academically, Ten Thousand Deng Jiaxians Cannot Match One Yang Zhenning","permalink":"/en/qiangguo/djxyzhn"}}'),r=t(74848),s=t(28453);let i={id:"briefsummary",title:"",hide_table_of_contents:!0,sidebar_label:"January Summary and Farewell to the Forum, Plus Revealing the Original Aliases and the Truth About the Japanese Couplet"},o="A One-Month Summary, Farewell to the Forum, Revealing My Previous Aliases and the Truth About the Japanese Couplet",l={},h=[];function u(e){let n={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"a-one-month-summary-farewell-to-the-forum-revealing-my-previous-aliases-and-the-truth-about-the-japanese-couplet",children:"A One-Month Summary, Farewell to the Forum, Revealing My Previous Aliases and the Truth About the Japanese Couplet"})}),"\n",(0,r.jsxs)(n.blockquote,{children:["\n",(0,r.jsx)(n.p,{children:"[Girl Who Likes Mathematics] posted on 2003-07-09 15:10:36"}),"\n"]}),"\n",(0,r.jsxs)(n.p,{children:["--------------------------------------------------------------------------------",(0,r.jsx)("br",{})]}),"\n",(0,r.jsxs)(n.p,{children:["From June 9th to today is exactly one month, and it's time to leave. If I offended any moderators or netizens during this time, I apologize here in advance. But first, I must reveal the truth about that Japanese couplet. Please look at this record:",(0,r.jsx)("br",{}),"\nUsername: JapanJapanJapanJapanJapanJapanJapan",(0,r.jsx)("br",{}),"\nRegistration date: 2003-05-31"]}),"\n",(0,r.jsx)(n.p,{children:'This was one of the aliases I used. I came up with that first line of the couplet while playing in Rizhao. I also came up with the second line at the same time, and posted them on different websites for fun. On June 1st, I posted it on the China-Japan forum, and at the time I even accidentally reversed the phrase "shine over all." All of this can be verified -- the records are still there. The moderator can confirm this, as I used the same email for all my registrations. At the time, it was purely for fun; I just hoped to remind all Chinese people to cherish their own culture. I never expected that the day before yesterday, someone on Shenshui reposted it from a Singaporean newspaper, and suddenly the whole world knew. The internet today is truly terrifying. My couplet: "From the East the sun of Japan rises, shining over the Four Countries and Nine Provinces; Dogen returns to emptiness and enlightenment, penetrating Yunmen and Fayan." It was designed along the lines of "Three lights: sun, moon, stars; four poems: Feng, Ya, Song" -- entirely out of respect for culture. I never anticipated things would turn out this way. It seems I underestimated the power of the internet. These past two days, I\'ve been teasing everyone like squeezing toothpaste, purely hoping to introduce more knowledge about couplets. So I hereby solemnly declare: this matter ends here. Stop playing with it. If not for that repost the day before yesterday, I wouldn\'t have wanted to bring this up again. "From the East the sun of Japan rises, shining over the Four Countries and Nine Provinces; Dogen returns to emptiness and enlightenment, penetrating Yunmen and Fayan" carries the same meaning as "Three lights: sun, moon, stars; four poems: Feng, Ya, Song" -- that culture triumphs over military force. It is also a reminder to Japan: even if you try tricks with military force, Chinese culture will ultimately prevail over you. Another original intention of this matter was to remind all Chinese people to treasure their own culture -- this is the ultimate driving force behind the Chinese nation\'s prosperity.'}),"\n",(0,r.jsx)(n.p,{children:"As for the alias I used on this forum last month, I believe many people already know. Think about it -- during SARS, what was the one thing people were most afraid of others doing? Finally, as per tradition, I'll bid farewell with the longest ci lyric form, \"Ying Ti Xu\" (Oriole's Cry Prelude):"}),"\n",(0,r.jsxs)(n.p,{children:["Swallows return beneath old eaves, calling fresh clear dawns to turn and look.",(0,r.jsx)("br",{}),"\nThin light drags on, scraping shadows into streaming haze, beading drop by drop into pure dew.",(0,r.jsx)("br",{}),"\nGoose-yellow tender, jade branches burst green; faint fragrance secretly follows the wind-strings in dance.",(0,r.jsx)("br",{}),"\nIllusory purple drifts, red ripples, in trance-like haze I seem to hear whispered words."]}),"\n",(0,r.jsxs)(n.p,{children:["Severed hair still tangles the heart, thirty years of butterfly dreams, where carriage dust rises in chaos.",(0,r.jsx)("br",{}),"\nAt Yichun Courtyard, smiling faces welcome pleasure, long used to idle men and resentful women.",(0,r.jsx)("br",{}),"\nFearing dawn and dusk, leaning alone on carved railings, still no tears, only a withered soul left empty.",(0,r.jsx)("br",{}),"\nThe jade brazier cold, vermilion curtains half rolled, sudden light mist arrives."]}),"\n",(0,r.jsxs)(n.p,{children:["At Blue Bridge the waters are old, boats lie crosswise on the far bank, distant hills wear pale snow.",(0,r.jsx)("br",{}),"\nAgain before my eyes, young peach blossoms blaze, teasing with color and flaunting their hues,",(0,r.jsx)("br",{}),"\nmixed scents divide and gather, like those years when we met.",(0,r.jsx)("br",{}),"\nAs slanting sunlight dies, a lonely sail slips inward; in blank sorrow where can longing rest?",(0,r.jsx)("br",{}),"\nSuddenly I wake, fourfold emerald fills the sky with flying plumes.",(0,r.jsx)("br",{}),"\nA few yellow clouds whirl into ten thousand thunder-running horses, red dust smothering the whole heaven."]}),"\n",(0,r.jsxs)(n.p,{children:["Spring chill hangs with the moon, wine warms the long night, yet at fourth watch rain is added.",(0,r.jsx)("br",{}),"\nDrop by drop, by the west window, impossible to remain still.",(0,r.jsx)("br",{}),"\nHolding candlelight before the screen, fragrant snow veining blue, drunken plum crossing white silk.",(0,r.jsx)("br",{}),"\nVaguely touchable, lotus-heart secrets, a jade zither leaves stone-like echoes distant and dim.",(0,r.jsx)("br",{}),"\nAs if hearing again old lines of yearning.",(0,r.jsx)("br",{}),"\nIn the eastern corner, hidden pale light slips back; hurriedly I fix my fading makeup as the guest calls me in."]})]})}function d(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(u,{...e})}):u(e)}},28453(e,n,t){t.d(n,{R:()=>i,x:()=>o});var a=t(96540);let r={},s=a.createContext(r);function i(e){let n=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),a.createElement(s.Provider,{value:n},e.children)}}}]);